// 01 - Simulated Sensor: one normalised reading per message
let s = context.get('sim') || { t: 32.4, h: 71.0, p: 1008.6 };

function walk(v, step, min, max) {
    v += (Math.random() - 0.5) * 2 * step;
    return Math.min(max, Math.max(min, v));
}

s.t = walk(s.t, 0.3, 20, 45);
s.h = walk(s.h, 1.0, 30, 95);
s.p = walk(s.p, 0.2, 990, 1020);
context.set('sim', s);

msg.payload = {
    device_id: "weather_node_01",
    temperature: Math.round(s.t * 10) / 10,
    humidity: Math.round(s.h * 10) / 10,
    pressure: Math.round(s.p * 10) / 10,
    pressure_type: "station",
    timestamp: new Date().toISOString(),
    source: "simulated"
};
global.set("sensor_latest", msg.payload);
return msg;

const key = env.get("OWM_API_KEY");
const lat = env.get("WX_LAT");
const lon = env.get("WX_LON");

if (!key || !lat || !lon) {
    msg.payload = {
        source: "openweathermap",
        ok: false,
        error: "Missing OWM_API_KEY, WX_LAT or WX_LON environment variable",
        fetched_at: new Date().toISOString()
    };
    return [null, msg];
}

msg.url = "https://api.openweathermap.org/data/2.5/weather?lat=" + encodeURIComponent(lat) +
    "&lon=" + encodeURIComponent(lon) +
    "&units=metric&appid=" + encodeURIComponent(key);
return [msg, null];

const now = new Date().toISOString();
const fail = (why) => {
    msg.payload = { source: "openweathermap", ok: false, error: why, fetched_at: now };
    global.set("api_latest", msg.payload);
    return msg;
};

if (msg.error) return fail("Request error: " + (msg.error.message || "unknown"));
if (msg.statusCode !== 200) return fail("HTTP " + msg.statusCode);

const d = msg.payload;
if (!d || !d.main || typeof d.main.temp !== "number" || typeof d.main.humidity !== "number") {
    return fail("Unexpected response shape");
}

msg.payload = {
    source: "openweathermap",
    ok: true,
    location_name: d.name || null,
    temperature: d.main.temp,
    humidity: d.main.humidity,
    pressure_msl: d.main.pressure,
    pressure_ground: (typeof d.main.grnd_level === "number") ? d.main.grnd_level : null,
    observed_at: new Date(d.dt * 1000).toISOString(),
    fetched_at: now
};
global.set("api_latest", msg.payload);
return msg;

msg.payload = {
    lat: env.get("WX_LAT"),
    lon: env.get("WX_LON"),
    key_length: (env.get("OWM_API_KEY") || "").length,
    os_check: env.get("USERPROFILE")
};
return msg;

const key = env.get("OWM_API_KEY");
const lat = env.get("WX_LAT");
const lon = env.get("WX_LON");

if (!key || !lat || !lon) {
    msg.payload = {
        source: "openweathermap_forecast",
        ok: false,
        error: "Missing OWM_API_KEY, WX_LAT or WX_LON environment variable",
        fetched_at: new Date().toISOString()
    };
    return [null, msg];
}

msg.url = "https://api.openweathermap.org/data/2.5/forecast?lat=" + encodeURIComponent(lat) +
    "&lon=" + encodeURIComponent(lon) +
    "&units=metric&cnt=8&appid=" + encodeURIComponent(key);
return [msg, null];

const now = new Date().toISOString();
const fail = (why) => {
    msg.payload = { source: "openweathermap_forecast", ok: false, error: why, fetched_at: now };
    global.set("forecast_latest", msg.payload);
    return msg;
};

if (msg.error) return fail("Request error: " + (msg.error.message || "unknown"));
if (msg.statusCode !== 200) return fail("HTTP " + msg.statusCode);

const d = msg.payload;
if (!d || !Array.isArray(d.list) || d.list.length === 0) return fail("Unexpected response shape");

const steps = d.list.map(e => ({
    time: new Date(e.dt * 1000).toISOString(),
    temperature: (e.main && typeof e.main.temp === "number") ? e.main.temp : null,
    humidity: (e.main && typeof e.main.humidity === "number") ? e.main.humidity : null,
    rain_probability_pct: (typeof e.pop === "number") ? Math.round(e.pop * 100) : null,
    rain_3h_mm: (e.rain && typeof e.rain["3h"] === "number") ? e.rain["3h"] : 0
}));

const pops = steps.map(s => s.rain_probability_pct).filter(v => v !== null);

msg.payload = {
    source: "openweathermap_forecast",
    ok: true,
    steps: steps,
    max_rain_probability_pct: pops.length ? Math.max(...pops) : null,
    total_rain_mm: Math.round(steps.reduce((a, s) => a + s.rain_3h_mm, 0) * 100) / 100,
    fetched_at: now
};
global.set("forecast_latest", msg.payload);
return msg;

const s = global.get("sensor_latest");
const a = global.get("api_latest");
const f = global.get("forecast_latest");
const now = Date.now();

const num = (v, d) => (typeof v === "number") ? v.toFixed(d) : "n/a";
const age = (iso) => {
    if (!iso) return "no data";
    const t = new Date(iso);
    const sec = Math.max(0, Math.round((now - t.getTime()) / 1000));
    const ago = sec < 90 ? sec + " s ago" : Math.round(sec / 60) + " min ago";
    return t.toLocaleTimeString("en-GB") + " (" + ago + ")";
};

const local = s ? {
    rows: [
        ["Source", s.source],
        ["Temperature", num(s.temperature, 1) + " °C"],
        ["Humidity", num(s.humidity, 0) + " %"],
        ["Pressure (station)", num(s.pressure, 1) + " hPa"],
        ["Updated", age(s.timestamp)]
    ]
} : { rows: [["Status", "No sensor data yet"]] };

let weather;
if (!a) {
    weather = { rows: [["Status", "No API data yet"]] };
} else if (!a.ok) {
    weather = { rows: [["Status", "API ERROR: " + a.error], ["Attempted", age(a.fetched_at)]] };
} else {
    weather = {
        rows: [
            ["Location", a.location_name || "n/a"],
            ["Temperature", num(a.temperature, 1) + " °C"],
            ["Humidity", num(a.humidity, 0) + " %"],
            ["Pressure (ground)", num(a.pressure_ground, 0) + " hPa"],
            ["Observed", age(a.observed_at)]
        ]
    };
}

let fc;
if (!f) {
    fc = { rows: [["Status", "No forecast data yet"]] };
} else if (!f.ok) {
    fc = { rows: [["Status", "API ERROR: " + f.error], ["Attempted", age(f.fetched_at)]] };
} else {
    fc = {
        rows: [
            ["Max rain chance", f.max_rain_probability_pct + " %"],
            ["Expected rain", f.total_rain_mm + " mm"],
            ["Fetched", age(f.fetched_at)]
        ]
    };
}

const c = global.get("comparison_latest");
const sgn = (v, d) => (v > 0 ? "+" : "") + v.toFixed(d);
let cmp;
if (!c) {
    cmp = { status: "WAITING", rows: [["", "No comparison result yet."]] };
} else if (now - new Date(c.evaluated_at).getTime() > 30000) {
    cmp = { status: "STALE", rows: [["", "The comparison has stopped updating, so these values may be outdated."]] };
} else {
    const rows = [];
    const t = c.temperature, h = c.humidity;
    if (t) rows.push(["Temperature", t.sensor.toFixed(1) + " °C (sensor) vs " + t.api.toFixed(1) +
        " °C (API) = " + sgn(t.delta, 1) + " °C (threshold ±" + t.threshold + " °C)"]);
    if (h && !h.skipped) rows.push(["Humidity", h.sensor.toFixed(0) + " % (sensor) vs " + h.api.toFixed(0) +
        " % (API) = " + sgn(h.delta, 1) + " percentage points (threshold ±" + h.threshold + ")"]);
    else if (h && h.skipped) rows.push(["Humidity", "not compared: " + h.reason]);
    c.messages.forEach((m) => rows.push(["", m]));
    rows.push(["Evaluated", age(c.evaluated_at)]);
    cmp = { status: c.status, rows: rows };
}

return [{ payload: local }, { payload: weather }, { payload: fc }, { payload: cmp }];

// 04 - Comparison Engine: sensor vs API. Pressure is intentionally not compared.
const cfg = Object.assign({
    temp_threshold_c: 3,
    humidity_threshold_pct: 10,
    sensor_stale_s: 60,
    api_fetch_stale_s: 1800,
    api_obs_stale_s: 3600,
    compare_humidity: true
}, global.get("config") || {});

const isTest = !!msg.test;
const s = isTest ? msg.test.sensor : global.get("sensor_latest");
const a = isTest ? msg.test.api : global.get("api_latest");
const nowMs = Date.now();

const ageS = (iso) => iso ? Math.round((nowMs - new Date(iso).getTime()) / 1000) : null;
const okNum = (v, lo, hi) => typeof v === "number" && isFinite(v) && v >= lo && v <= hi;
const r1 = (v) => Math.round(v * 10) / 10;

const result = {
    status: "NO_COMPARISON",
    messages: [],
    temperature: null,
    humidity: null,
    sensor_age_s: s ? ageS(s.timestamp) : null,
    api_fetch_age_s: a ? ageS(a.fetched_at) : null,
    api_obs_age_s: (a && a.ok) ? ageS(a.observed_at) : null,
    config: cfg,
    evaluated_at: new Date(nowMs).toISOString()
};
if (isTest) result.test_name = msg.test.name;

const problems = [];
if (!s) problems.push("No sensor data yet.");
else if (result.sensor_age_s === null) problems.push("Sensor reading has no valid timestamp.");
else if (result.sensor_age_s > cfg.sensor_stale_s) problems.push("Sensor data is stale (" + result.sensor_age_s + " s old).");
else if (!okNum(s.temperature, -40, 85)) problems.push("Sensor temperature is missing or out of range.");

if (!a) problems.push("No weather API data yet.");
else if (!a.ok) problems.push("Weather API unavailable: " + a.error);
else if (result.api_fetch_age_s === null || result.api_fetch_age_s > cfg.api_fetch_stale_s) problems.push("Weather API data has not been refreshed recently.");
else if (result.api_obs_age_s === null || result.api_obs_age_s > cfg.api_obs_stale_s) problems.push("Weather API observation is old (" + result.api_obs_age_s + " s).");
else if (!okNum(a.temperature, -60, 60)) problems.push("API temperature is missing or out of range.");

if (problems.length) {
    result.messages = problems;
} else {
    const dT = r1(s.temperature - a.temperature);
    result.temperature = {
        sensor: s.temperature, api: a.temperature, delta: dT, unit: "°C",
        threshold: cfg.temp_threshold_c, exceeded: Math.abs(dT) >= cfg.temp_threshold_c
    };

    if (cfg.compare_humidity && okNum(s.humidity, 0, 100) && okNum(a.humidity, 0, 100)) {
        const dH = r1(s.humidity - a.humidity);
        result.humidity = {
            sensor: s.humidity, api: a.humidity, delta: dH, unit: "percentage points",
            threshold: cfg.humidity_threshold_pct, exceeded: Math.abs(dH) >= cfg.humidity_threshold_pct
        };
    } else {
        result.humidity = { skipped: true, reason: cfg.compare_humidity ? "Humidity value missing or invalid." : "Humidity comparison disabled in config." };
    }

    const t = result.temperature, h = result.humidity;
    if (t.exceeded) {
        result.messages.push("The local sensor reports " + t.sensor.toFixed(1) + "°C, while the weather service reports " +
            t.api.toFixed(1) + "°C. The local environment is " + Math.abs(t.delta).toFixed(1) + "°C " +
            (t.delta > 0 ? "warmer" : "cooler") + " than the reported conditions. This may be due to sensor placement " +
            "(indoors, direct sunlight, nearby heat sources), measurement location, timing, or calibration differences.");
    }
    if (h && !h.skipped && h.exceeded) {
        result.messages.push("Local relative humidity is " + h.sensor.toFixed(0) + "%, versus " + h.api.toFixed(0) +
            "% reported: " + Math.abs(h.delta).toFixed(0) + " percentage points " + (h.delta > 0 ? "higher" : "lower") +
            ". Humidity varies strongly with sensor placement and temperature, so a difference does not by itself indicate a fault.");
    }

    if (result.messages.length) {
        result.status = "MISMATCH";
    } else {
        result.status = "OK";
        result.messages.push("No significant mismatch detected under the configured thresholds.");
    }
}

if (!isTest) global.set("comparison_latest", result);
msg.payload = result;
return msg;

// name, sensor [temp, humidity], api [temp, humidity], optional sensor age in seconds
const cases = [
    { name: "Sensor warmer (+4.5 C)", s: [34.0, 71], a: [29.5, 72] },
    { name: "Sensor cooler (-4.0 C)", s: [26.0, 72], a: [30.0, 71] },
    { name: "Sensor more humid (+15 pp)", s: [30.0, 85], a: [29.5, 70] },
    { name: "No mismatch", s: [30.0, 70], a: [29.5, 72] },
    { name: "Stale sensor (600 s old)", s: [30.0, 70], a: [29.5, 72], age: 600 }
];
const n = context.get("n") || 0;
const c = cases[n % cases.length];
context.set("n", n + 1);

const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();
msg.test = {
    name: c.name,
    sensor: { temperature: c.s[0], humidity: c.s[1], timestamp: new Date(nowMs - (c.age || 0) * 1000).toISOString() },
    api: { ok: true, temperature: c.a[0], humidity: c.a[1], observed_at: nowIso, fetched_at: nowIso }
};
return msg;

// 05 - Alert Configuration: validate dashboard input, save to global "config"
const defaults = { temp_threshold_c: 3, humidity_threshold_pct: 10, sensor_stale_s: 60, compare_humidity: true };
const current = Object.assign({}, defaults, global.get("config") || {});

const rules = {
    temp_threshold_c: { min: 0.5, max: 20, label: "Temperature threshold (°C)" },
    humidity_threshold_pct: { min: 1, max: 50, label: "Humidity threshold (percentage points)" },
    sensor_stale_s: { min: 10, max: 3600, label: "Sensor stale limit (s)" }
};

const p = msg.payload;
let outcome = "Showing current settings.";

if (typeof p === "boolean") {
    current.compare_humidity = p;
    global.set("config", Object.assign({}, current));
    outcome = "Humidity comparison turned " + (p ? "on" : "off") + " at " + new Date().toLocaleTimeString("en-GB") + ".";
} else if (p && typeof p === "object" && !Array.isArray(p)) {
    const next = Object.assign({}, current);
    const errors = [];
    for (const key of Object.keys(rules)) {
        if (p[key] === undefined || p[key] === null || p[key] === "") continue;
        const v = Number(p[key]);
        const r = rules[key];
        if (!isFinite(v) || v < r.min || v > r.max) {
            errors.push(r.label + " must be from " + r.min + " to " + r.max + ".");
        } else {
            next[key] = v;
        }
    }
    if (errors.length) {
        outcome = "REJECTED, nothing saved. " + errors.join(" ");
    } else {
        global.set("config", next);
        Object.assign(current, next);
        outcome = "Saved at " + new Date().toLocaleTimeString("en-GB") + ".";
    }
}

msg.payload = {
    rows: [
        ["Temperature threshold", "±" + current.temp_threshold_c + " °C"],
        ["Humidity threshold", "±" + current.humidity_threshold_pct + " percentage points"],
        ["Sensor stale after", current.sensor_stale_s + " s"],
        ["Humidity comparison", current.compare_humidity ? "On" : "Off"],
        ["Last action", outcome],
        ["", "Prototype demonstration values, not validated safety limits."]
    ]
};
return msg;

const nowMs = Date.now();
const iso = (offS) => new Date(nowMs - offS * 1000).toISOString();
const sens = (t, h, age) => ({ temperature: t, humidity: h, timestamp: iso(age || 0), source: "test" });
const api = (t, h) => ({ ok: true, temperature: t, humidity: h, fetched_at: iso(0), observed_at: iso(0) });
const fc = (p, mm) => ({
    ok: true, max_rain_probability_pct: p, total_rain_mm: mm, fetched_at: iso(0),
    steps: [{ time: new Date(nowMs + 3 * 3600 * 1000).toISOString(), rain_probability_pct: p, rain_3h_mm: mm }]
});
const bad = { ok: false, error: "HTTP 401", fetched_at: iso(0) };

const cases = [
    { name: "Extreme heat", sensor: sens(39, 50), api: api(36, 60), forecast: fc(10, 0) },
    { name: "Hot and humid", sensor: sens(33, 80), api: api(32, 78), forecast: fc(10, 0) },
    { name: "Comfortable, rain likely", sensor: sens(24, 60), api: api(24, 62), forecast: fc(75, 12) },
    { name: "Cold", sensor: sens(8, 50), api: api(9, 55), forecast: fc(5, 0) },
    { name: "Stale sensor, API fallback", sensor: sens(30, 60, 600), api: api(29, 70), forecast: fc(40, 2) },
    { name: "No usable data", sensor: sens(30, 60, 600), api: bad, forecast: bad }
];
const n = context.get("n") || 0;
context.set("n", n + 1);
msg.test = cases[n % cases.length];
return msg;

// 06 - Safety Recommendations: simple rule-based advice (prototype, not medical advice)
const T = {                       // prototype thresholds: adjust here
    extreme_heat_c: 38, hot_c: 32, warm_c: 26, cool_c: 18, cold_c: 10,
    hot_humid_c: 30, humid_pct: 70,
    rain_high_pct: 60, rain_some_pct: 30, rain_heavy_mm: 10
};
const cfg = Object.assign({ sensor_stale_s: 60, api_fetch_stale_s: 1800, compare_humidity: true },
    global.get("config") || {});

const isTest = !!msg.test;
const s = isTest ? msg.test.sensor : global.get("sensor_latest");
const a = isTest ? msg.test.api : global.get("api_latest");
const f = isTest ? msg.test.forecast : global.get("forecast_latest");
const c = isTest ? null : global.get("comparison_latest");

const now = Date.now();
const ageS = (iso) => iso ? Math.round((now - new Date(iso).getTime()) / 1000) : null;
const num = (v) => typeof v === "number" && isFinite(v);
const LEVELS = { INFO: 0, WARNING: 1, CRITICAL: 2 };
const items = [];
const add = (level, label, text) => items.push({ level, label, text });

const sensorFresh = !!s && num(s.temperature) && ageS(s.timestamp) !== null && ageS(s.timestamp) <= cfg.sensor_stale_s;
const apiFresh = !!a && a.ok === true && num(a.temperature) && ageS(a.fetched_at) !== null && ageS(a.fetched_at) <= cfg.api_fetch_stale_s;
const fcFresh = !!f && f.ok === true && ageS(f.fetched_at) !== null && ageS(f.fetched_at) <= cfg.api_fetch_stale_s;

let temp = null, hum = null, basis = null;
if (sensorFresh) {
    temp = s.temperature;
    if (cfg.compare_humidity && num(s.humidity)) hum = s.humidity;
    else if (apiFresh && num(a.humidity)) hum = a.humidity;
    basis = "local sensor";
} else if (apiFresh) {
    temp = a.temperature;
    hum = num(a.humidity) ? a.humidity : null;
    basis = "weather API (local sensor missing or stale)";
}

if (temp === null) {
    add("WARNING", "Status", "No recent temperature data, so no clothing or heat advice can be given.");
} else {
    const tt = temp.toFixed(1) + " °C";
    if (temp >= T.extreme_heat_c) {
        add("CRITICAL", "Heat", "Extreme heat (" + tt + "). Avoid strenuous outdoor activity, stay in a cool place, drink water regularly, and check on others.");
    } else if (temp >= T.hot_c) {
        add("WARNING", "Heat", "Hot (" + tt + "). Drink water regularly and take breaks in cool or shaded areas.");
    }
    let clothing;
    if (temp >= T.warm_c) clothing = "Lightweight, breathable, light-coloured clothing.";
    else if (temp >= T.cool_c) clothing = "Comfortable everyday clothing.";
    else if (temp >= T.cold_c) clothing = "A light jacket or an extra layer.";
    else clothing = "Warm layers.";
    add("INFO", "Clothing", clothing);

    if (hum !== null && temp >= T.hot_humid_c && hum >= T.humid_pct) {
        add("WARNING", "Hot and humid", "Humidity is " + hum.toFixed(0) + " %, so sweat evaporates less easily. Reduce strenuous activity and watch for heat-related symptoms such as dizziness, headache or nausea.");
    }
}

if (!fcFresh) {
    add("INFO", "Rain", "Forecast data is unavailable or outdated, so there is no rain advice.");
} else if (num(f.max_rain_probability_pct)) {
    const peak = (f.steps || []).reduce((best, st) =>
        (st.rain_probability_pct !== null && (best === null || st.rain_probability_pct > best.rain_probability_pct)) ? st : best, null);
    const when = peak ? " Peak chance around " + new Date(peak.time).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }) + "." : "";
    const p = f.max_rain_probability_pct;
    if (p >= T.rain_high_pct || f.total_rain_mm >= T.rain_heavy_mm) {
        add("WARNING", "Rain", "Rain is likely in the next 24 h (up to " + p + " %, about " + f.total_rain_mm + " mm in total). Carry an umbrella or raincoat." + when);
    } else if (p >= T.rain_some_pct) {
        add("INFO", "Rain", "Some chance of rain (up to " + p + " %). An umbrella may be useful." + when);
    } else {
        add("INFO", "Rain", "Low chance of rain in the next 24 h (up to " + p + " %).");
    }
}

if (c && c.status === "MISMATCH" && ageS(c.evaluated_at) !== null && ageS(c.evaluated_at) <= 30) {
    add("INFO", "Local vs report", "Local readings differ noticeably from the weather report (see the comparison card). The advice above uses the " + (basis || "available data") + ".");
}

const problems = [];
if (!sensorFresh) problems.push("local sensor data is missing or stale");
if (!apiFresh) problems.push("current weather data is missing or outdated");
if (!fcFresh) problems.push("forecast data is missing or outdated");
if (problems.length) {
    add("WARNING", "Data status", "Recommendations may be outdated: " + problems.join("; ") + ".");
}

items.sort((x, y) => LEVELS[y.level] - LEVELS[x.level]);
const top = items.length ? items[0].level : "INFO";
const basisText = temp === null ? "no recent data"
    : basis + " (" + temp.toFixed(1) + " °C" + (hum !== null ? ", " + hum.toFixed(0) + " % RH" : "") + ")";

const rows = [["Based on", basisText]];
items.forEach((i) => rows.push([i.label, "[" + i.level + "] " + i.text]));
rows.push(["", "UV index and air quality are not measured by this prototype. General guidance from simple rules, not medical advice."]);
rows.push(["Updated", new Date(now).toLocaleTimeString("en-GB")]);
if (isTest) rows.unshift(["TEST CASE", msg.test.name]);

msg.payload = { level: top, rows: rows };
if (isTest) return [null, msg];
global.set("recommendations_latest", msg.payload);
return [msg, null];
